INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Taktfrequenz immer der Hauptfaktor für die Leistung?', 2, '[{"text": "Nein", "correct": true, "because": "Kernanzahl und Architektur spielen mit"}, {"text": "Ja", "correct": false, "because": "Nur ein Teil der Gleichung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beeinflusst meine CPU-Leistung am meisten bei parallelen Tasks?', 3, '[{"text": "Anzahl der Kerne", "correct": true, "because": "Mehr Kerne, mehr Parallelität"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hilft nur bei Einzelthreads"}, {"text": "Großer Cache", "correct": false, "because": "Sekundär bei Multitasking"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine CPU für Virtualisierung geeignet?', 5, '[{"text": "Hohe Kernanzahl", "correct": true, "because": "Mehr VMs gleichzeitig"}, {"text": "Hardware-Virtualisierung", "correct": true, "because": "Effiziente VM-Steuerung"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Weniger relevant"}, {"text": "Onboard-Grafik", "correct": false, "because": "Irrelevant für VMs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mehr Kerne bedeuten immer mehr Leistung. b) Taktfrequenz ist bei Spielen entscheidend.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) hängt von der Software ab"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist kontextabhängig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine CPU für einen Server auswähle?', 4, '[{"text": "Kernanzahl", "correct": false, "because": "Wichtig für Lasten"}, {"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Performance"}, {"text": "Integrierte Grafik", "correct": true, "because": "Server nutzen oft dedizierte GPUs"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Single-Core immer langsamer ist als ein Multi-Core?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von der Aufgabe ab"}, {"text": "Ja", "correct": false, "because": "Single-Core kann bei Einzelthreads gewinnen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft priorisiere ich für eine Datenbank-CPU?', 3, '[{"text": "Hohe Kernanzahl", "correct": true, "because": "Parallele Abfragen effizient"}, {"text": "Maximale Taktfrequenz", "correct": false, "because": "Weniger relevant"}, {"text": "Großer L3-Cache", "correct": false, "because": "Hilfreich, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features sind bei einer modernen CPU entscheidend?', 5, '[{"text": "Multi-Threading", "correct": true, "because": "Mehr Aufgaben pro Kern"}, {"text": "Hohe Taktfrequenz", "correct": true, "because": "Schnelle Einzelaufgaben"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Sekundär"}, {"text": "Integrierte GPU", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Taktfrequenz ist wichtiger als Kerne. b) Multi-Core hilft nur bei Multitasking. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) kontextabhängig, b) auch bei Single-Apps nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "Beides zu pauschal"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) nicht immer"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) zu eng"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Gaming-CPU?', 4, '[{"text": "Hohe Taktfrequenz", "correct": false, "because": "Wichtig für FPS"}, {"text": "Mehrere Kerne", "correct": false, "because": "Moderne Spiele nutzen sie"}, {"text": "Serveroptimierung", "correct": true, "because": "Nicht gamingrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind zwei Kerne immer besser als einer?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von der Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine CPU für Rendering stark?', 4, '[{"text": "Viele Kerne", "correct": true, "because": "Parallele Berechnungen"}, {"text": "Hoher Cache", "correct": true, "because": "Schneller Datenzugriff"}, {"text": "Maximale Taktfrequenz", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine höhere Taktfrequenz immer mehr Strom verbraucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Mehr Hertz, mehr Energie"}, {"text": "Nein", "correct": false, "because": "Architektur kann kompensieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer CPU für eine Workstation?', 3, '[{"text": "Balance aus Kernen und Takt", "correct": true, "because": "Vielseitige Aufgaben"}, {"text": "Nur hohe Taktfrequenz", "correct": false, "because": "Zu einseitig"}, {"text": "Minimaler Stromverbrauch", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hyper-Threading verdoppelt die Kerne. b) Es verbessert Multitasking.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist virtuell, keine echten Kerne"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Multi-Core-CPU?', 5, '[{"text": "Parallele Verarbeitung", "correct": true, "because": "Mehr Aufgaben gleichzeitig"}, {"text": "Bessere Skalierbarkeit", "correct": true, "because": "Für komplexe Anwendungen"}, {"text": "Geringere Latenz", "correct": false, "because": "Nicht direkt"}, {"text": "Einfachere Kühlung", "correct": false, "because": "Mehr Kerne, mehr Wärme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer CPU für einen Thin Client unwichtig?', 3, '[{"text": "Kernanzahl", "correct": false, "because": "Minimal nötig"}, {"text": "Taktfrequenz", "correct": false, "because": "Für Basisaufgaben relevant"}, {"text": "High-End-Features", "correct": true, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beeinflusst die Architektur die Leistung mehr als die Taktfrequenz?', 3, '[{"text": "Ja", "correct": true, "because": "Effizienz schlägt rohe Geschwindigkeit"}, {"text": "Nein", "correct": false, "because": "Architektur ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine CPU mit mehr Kernen immer teurer ist?', 2, '[{"text": "Nein", "correct": true, "because": "Preis hängt auch von Typ ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CPU-Eigenschaft wähle ich für einen Webserver?', 4, '[{"text": "Hohe Kernanzahl", "correct": true, "because": "Viele Anfragen parallel"}, {"text": "Maximale Taktfrequenz", "correct": false, "because": "Weniger kritisch"}, {"text": "Integrierte GPU", "correct": false, "because": "Nicht benötigt"}]');
